    { id: 'gold', name: 'Gold', hex: '#e6c04a' },
    { id: 'onyx', name: 'Onyx', hex: '#2c2733' },
  ];

  const FACE_SHAPES = [
    { id: 'round', name: 'Round Face', tw: 38, cw: 17, chinY: 116 },
