  const BODY_TYPES = [
    { id: 'petite', name: 'Petite', sw: 29, lift: 6, bust: 0.0 },
    { id: 'slim', name: 'Slim', sw: 32, lift: 2, bust: 0.15 },
    { id: 'curvy', name: 'Curvy', sw: 33, lift: 0, bust: 0.9 },
