/* ============================================================
   Petal Town Hearts — early-aughts anime dating sim UI
   ============================================================ */
:root {
  --pink: #ff8fc2;
  --pink-d: #d84f8b;
  --lilac: #c9a8f0;
  --sky: #8fd3f4;
  --cream: #fff6fb;
  --ink: #4a3540;
  --gold: #ffd76e;
  --green: #7ed6a8;
  --panel: linear-gradient(160deg, #fff3fa 0%, #ffe3f1 55%, #f3d9ff 100%);
  --shadow: 0 6px 0 rgba(216, 79, 139, .25), 0 10px 22px rgba(180, 90, 150, .22);
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  font-family: 'Fredoka', 'Trebuchet MS', 'Comic Sans MS', sans-serif;
  color: var(--ink);
  background:
    radial-gradient(circle at 15% 10%, #ffe9f6 0 12%, transparent 40%),
    radial-gradient(circle at 85% 0%, #e8dcff 0 10%, transparent 38%),
    linear-gradient(180deg, #ffeef8 0%, #f7e6ff 45%, #e7f4ff 100%);
  overflow: hidden;
}

/* ---------------- HUD ---------------- */
#hud {
  display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
  padding: 8px 14px;
  background: linear-gradient(180deg, #ffd7ea, #ffb9da);
  border-bottom: 3px solid #fff;
  box-shadow: 0 4px 14px rgba(216, 79, 139, .3);
  position: relative; z-index: 5;
}
.logo { font-size: 20px; letter-spacing: .3px; }
.logo b {
  background: linear-gradient(90deg, #d84f8b, #8a5fd6);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.logo i { font-size: 11px; color: #a06c92; margin-left: 4px; }
.hud-stats { display: flex; gap: 8px; flex-wrap: wrap; }
.stat {
  font-family: 'VT323', monospace; font-size: 20px; line-height: 1;
  padding: 5px 10px; border-radius: 999px; background: #fff;
  border: 2px solid var(--pink); box-shadow: 0 3px 0 rgba(216, 79, 139, .3);
  white-space: nowrap;
}
.stat.money { background: #fffbe8; border-color: #e8b93f; color: #8a6a12; }
.stat.perk { background: #f3ecff; border-color: #a882e0; color: #6a4aa0; }
.hud-goal { margin-left: auto; display: flex; align-items: center; gap: 8px; font-size: 12px; }
.goal-bar { width: 150px; height: 12px; border-radius: 999px; background: #fff; border: 2px solid var(--pink); overflow: hidden; }
.goal-bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--gold), var(--pink)); transition: width .5s; }

/* ---------------- layout ---------------- */
#layout {
  display: grid; grid-template-columns: 1fr 372px; gap: 12px;
  padding: 12px; height: calc(100vh - 56px);
}
#stage { display: flex; flex-direction: column; gap: 10px; min-width: 0; overflow: hidden; }

#mapWrap {
  border-radius: 18px; overflow: hidden; border: 3px solid #fff;
  box-shadow: var(--shadow); background: #cdeafd; flex: 0 0 auto;
}
#map { display: block; width: 100%; height: min(38vh, 330px); }
.loc { cursor: pointer; }
.loc rect { transition: transform .15s; }
.loc:hover rect { stroke: var(--pink-d); stroke-width: 3; }
.loc.here rect { stroke: var(--pink-d); stroke-width: 4; filter: drop-shadow(0 0 6px #ff8fc2); }
#marker { transition: transform .6s cubic-bezier(.34,1.4,.5,1); }

#scene {
  flex: 1 1 auto; min-height: 0; overflow-y: auto;
  border-radius: 18px; border: 3px solid #fff; box-shadow: var(--shadow);
  background: var(--panel); padding: 12px;
}

#logWrap {
  flex: 0 0 auto; border-radius: 14px; border: 3px solid #fff; box-shadow: var(--shadow);
  background: linear-gradient(180deg, #fffdf5, #fff3fb); padding: 6px 10px 8px;
  max-height: 128px; display: flex; flex-direction: column;
}
.log-title { font-size: 13px; font-weight: 700; color: #b0608c; }
#log { margin: 2px 0 0; padding: 0; list-style: none; overflow-y: auto; font-size: 12.5px; line-height: 1.5; }
#log li { padding: 1px 0; border-bottom: 1px dashed #f3d3e6; }
#log li b { color: #d84f8b; font-family: 'VT323', monospace; font-size: 15px; }

/* ---------------- right rail menu ---------------- */
#rail {
  display: grid; grid-template-rows: auto 1fr auto; gap: 8px;
  background: var(--panel); border-radius: 18px; border: 3px solid #fff;
  box-shadow: var(--shadow); padding: 10px; min-height: 0;
}
.rail-head { text-align: center; }
#menuTitle {
  font-size: 17px; font-weight: 700; color: #fff;
  background: linear-gradient(90deg, var(--pink), var(--lilac));
  border-radius: 999px; padding: 5px 12px; border: 2px solid #fff;
  box-shadow: 0 3px 0 rgba(160, 90, 160, .35);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
#menuHint { font-size: 11px; color: #a6748f; margin-top: 4px; }

#menuList {
  overflow-y: auto; display: flex; flex-direction: column; gap: 7px;
  padding: 4px 3px 4px 0; outline: none; scroll-behavior: smooth;
}
#menuList::-webkit-scrollbar { width: 9px; }
#menuList::-webkit-scrollbar-thumb { background: linear-gradient(var(--pink), var(--lilac)); border-radius: 999px; }
#menuList::-webkit-scrollbar-track { background: #fff; border-radius: 999px; }

.mi {
  display: grid; grid-template-columns: 30px 1fr auto; align-items: center; gap: 8px;
  padding: 8px 9px; border-radius: 13px; cursor: pointer; text-align: left;
  background: linear-gradient(180deg, #ffffff, #ffeef8);
  border: 2px solid #ffc2dd; color: var(--ink); font-family: inherit; font-size: 13.5px;
  box-shadow: 0 3px 0 rgba(216, 79, 139, .22); transition: transform .08s, box-shadow .08s;
}
.mi:hover { transform: translateY(-1px); }
.mi.sel { border-color: var(--pink-d); background: linear-gradient(180deg, #fff0f7, #ffd9ec); box-shadow: 0 0 0 3px rgba(255, 143, 194, .35), 0 3px 0 rgba(216, 79, 139, .3); }
.mi.dis { opacity: .55; cursor: not-allowed; filter: grayscale(.4); }
.mi .ic { font-size: 19px; text-align: center; }
.mi .lb { line-height: 1.15; }
.mi .lb small { display: block; color: #a6748f; font-size: 11px; margin-top: 1px; }
.mi .tag {
  font-family: 'VT323', monospace; font-size: 16px; color: #8a6a12;
  background: #fffbe8; border: 2px solid #f0cf77; border-radius: 999px; padding: 1px 8px; white-space: nowrap;
}
.mi .tag.heart { color: #d84f8b; background: #fff0f6; border-color: #ffb2d2; }
.mi .tag.lv { color: #6a4aa0; background: #f5efff; border-color: #c4a8ec; }
.mi.back { background: linear-gradient(180deg, #f6f2ff, #ece4ff); border-color: #cdb8ee; }

.rail-btns { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.rail-btn {
  font-family: inherit; font-size: 22px; font-weight: 700; color: #fff; cursor: pointer;
  padding: 9px 4px 6px; border-radius: 14px; border: 3px solid #fff;
  background: linear-gradient(180deg, var(--pink), var(--pink-d));
  box-shadow: 0 5px 0 #b23f75, 0 8px 14px rgba(180, 63, 117, .35);
  display: flex; flex-direction: column; align-items: center; line-height: 1;
  transition: transform .06s, box-shadow .06s; text-shadow: 0 2px 0 rgba(120, 30, 70, .35);
}
.rail-btn small { font-size: 9px; letter-spacing: 1px; margin-top: 3px; }
.rail-btn.down { background: linear-gradient(180deg, var(--lilac), #8a5fd6); box-shadow: 0 5px 0 #6a4aa0, 0 8px 14px rgba(106, 74, 160, .35); text-shadow: 0 2px 0 rgba(60, 30, 110, .35); }
.rail-btn:active { transform: translateY(4px); box-shadow: 0 1px 0 #b23f75; }

/* ---------------- scene content ---------------- */
.loc-head { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; }
.loc-head .ic { font-size: 30px; filter: drop-shadow(0 2px 2px rgba(0,0,0,.15)); }
.loc-head h2 { margin: 0; font-size: 20px; color: #b0447c; }
.loc-head p { margin: 2px 0 0; font-size: 12.5px; color: #8a6a7c; }
.sect { margin-top: 10px; }
.sect > h3 {
  margin: 0 0 6px; font-size: 13px; text-transform: uppercase; letter-spacing: 1px;
  color: #a2578a; display: flex; align-items: center; gap: 6px;
}
.sect > h3::after { content: ''; flex: 1; height: 2px; background: linear-gradient(90deg, #ffc2dd, transparent); border-radius: 2px; }

.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(154px, 1fr)); gap: 10px; }
.card {
  background: linear-gradient(180deg, #fff, #fff0f8); border: 2px solid #ffc2dd;
  border-radius: 14px; padding: 7px; text-align: center; box-shadow: 0 3px 0 rgba(216,79,139,.2);
  display: flex; flex-direction: column; gap: 3px; align-items: center;
}
.card .portrait { width: 100%; max-width: 120px; border-radius: 10px; background: #fff; }
.card .nm { font-weight: 700; font-size: 13px; }
.card .job { font-size: 11px; color: #9a6c86; margin-top: -3px; }
.card .meta { font-size: 11px; color: #7a6a72; }
.card.wife { border-color: #ff9ec4; background: linear-gradient(180deg, #fff, #ffe4f0); }
.card.kid { border-color: #c9b2f0; background: linear-gradient(180deg, #fff, #f3ecff); }
.badge {
  font-size: 10px; font-weight: 700; padding: 1px 7px; border-radius: 999px;
  background: #ff9ec4; color: #fff; letter-spacing: .5px;
}
.badge.girl { background: #ff9ec4; } .badge.boy { background: #7fa8d8; }
.badge.wifey { background: linear-gradient(90deg, #ffb2d2, #d84f8b); }
.affbar { width: 100%; height: 11px; border-radius: 999px; background: #fff; border: 2px solid #ffc2dd; overflow: hidden; }
.affbar i { display: block; height: 100%; background: linear-gradient(90deg, #ffd76e, #ff8fc2); transition: width .5s; }
.card .aff-txt { font-size: 11px; font-weight: 600; }

.preview-wrap { display: flex; gap: 14px; align-items: flex-start; flex-wrap: wrap; }
.preview-wrap .pv {
  flex: 0 0 auto; width: 220px; background: #fff; border-radius: 16px; padding: 6px;
  border: 3px solid var(--pink); box-shadow: var(--shadow);
}
.preview-wrap .pv svg { width: 100%; border-radius: 10px; }
.pv-facts { flex: 1 1 220px; min-width: 200px; font-size: 13px; }
.pv-facts table { border-collapse: collapse; width: 100%; }
.pv-facts td { padding: 3px 6px; border-bottom: 1px dashed #f0cfe2; }
.pv-facts td:first-child { color: #a2578a; font-weight: 600; width: 46%; }

.chips { display: flex; gap: 6px; flex-wrap: wrap; }
.chip {
  font-size: 11px; padding: 2px 8px; border-radius: 999px; background: #fff;
  border: 2px solid #ffc2dd; color: #a2578a;
}

/* ---------------- toast + modal ---------------- */
#toast {
  position: fixed; left: 50%; bottom: 22px; transform: translate(-50%, 40px);
  background: linear-gradient(180deg, #fff, #ffe6f2); border: 3px solid var(--pink);
  border-radius: 999px; padding: 10px 20px; font-weight: 600; font-size: 14px;
  box-shadow: var(--shadow); opacity: 0; pointer-events: none; transition: all .3s; z-index: 40;
  max-width: min(760px, 92vw); text-align: center;
}
#toast.show { opacity: 1; transform: translate(-50%, 0); }

#modal {
  position: fixed; inset: 0; background: rgba(120, 60, 100, .45); backdrop-filter: blur(3px);
  display: flex; align-items: center; justify-content: center; z-index: 50; padding: 16px;
}
#modal.hidden { display: none; }
.sheet {
  background: var(--panel); border: 4px solid #fff; border-radius: 22px;
  box-shadow: var(--shadow); padding: 20px; max-width: 620px; width: 100%;
  max-height: 90vh; overflow-y: auto; text-align: center; position: relative;
}
.sheet h1 { margin: 0 0 4px; font-size: 28px; color: #d84f8b; text-shadow: 0 2px 0 #fff; }
.sheet h2 { margin: 0 0 6px; font-size: 20px; color: #8a5fd6; }
.sheet p { font-size: 14px; color: #7a5a6c; line-height: 1.55; }
.field { display: flex; flex-direction: column; gap: 4px; margin: 10px 0; text-align: left; }
.field label { font-size: 12px; font-weight: 700; color: #a2578a; letter-spacing: .5px; }
.field input {
  font-family: inherit; font-size: 16px; padding: 9px 12px; border-radius: 12px;
  border: 2px solid var(--pink); background: #fff; color: var(--ink); outline: none;
}
.genders { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.gbtn {
  font-family: inherit; font-size: 15px; font-weight: 700; cursor: pointer; padding: 12px;
  border-radius: 14px; border: 3px solid #fff; background: linear-gradient(180deg, #fff, #ffe6f2);
  box-shadow: 0 4px 0 rgba(216, 79, 139, .25); color: var(--ink);
}
.gbtn.m { background: linear-gradient(180deg, #eaf3ff, #cfe6ff); box-shadow: 0 4px 0 rgba(80, 130, 200, .3); }
.gbtn.on { border-color: var(--pink-d); box-shadow: 0 0 0 4px rgba(255, 143, 194, .4); }
.gbtn small { display: block; font-weight: 400; font-size: 11px; color: #8a6a7c; }
.big-btn {
  font-family: inherit; font-size: 17px; font-weight: 700; color: #fff; cursor: pointer;
  padding: 12px 22px; border-radius: 999px; border: 3px solid #fff; margin-top: 8px;
  background: linear-gradient(180deg, var(--pink), var(--pink-d));
  box-shadow: 0 5px 0 #b23f75, 0 10px 18px rgba(180, 63, 117, .35);
}
.big-btn.alt { background: linear-gradient(180deg, var(--lilac), #8a5fd6); box-shadow: 0 5px 0 #6a4aa0, 0 10px 18px rgba(106, 74, 160, .35); }
.big-btn:active { transform: translateY(4px); box-shadow: 0 1px 0 #b23f75; }
.baby-row { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-top: 10px; }
.baby {
  background: #fff; border: 3px solid #c9b2f0; border-radius: 16px; padding: 8px; width: 150px;
  box-shadow: var(--shadow); animation: pop .5s cubic-bezier(.3,1.6,.5,1);
}
.baby svg { width: 100%; border-radius: 10px; }
.baby .nm { font-weight: 700; font-size: 13px; margin-top: 3px; }
@keyframes pop { from { transform: scale(.4); opacity: 0; } to { transform: scale(1); opacity: 1; } }
.confetti { position: fixed; inset: 0; pointer-events: none; z-index: 60; overflow: hidden; }
.confetti i {
  position: absolute; top: -20px; width: 10px; height: 14px; border-radius: 2px; opacity: .95;
  animation: fall linear forwards;
}
@keyframes fall { to { transform: translateY(110vh) rotate(720deg); opacity: .2; } }

/* ---------------- responsive ---------------- */
@media (max-width: 900px) {
  body { overflow: auto; }
  #layout { grid-template-columns: 1fr; height: auto; }
  #scene { max-height: 46vh; }
  #rail { position: sticky; bottom: 0; z-index: 6; }
  #menuList { max-height: 220px; }
  #map { height: 210px; }
  .hud-goal { margin-left: 0; }
}

/* ============================================================
   ui.js — map, scenes, side-scroll menu, customization, modals
   ============================================================ */
(function (global) {
  'use strict';
  const D = global.GameData, T = global.Traits, P = global.Portrait;
  const $ = (s) => document.querySelector(s);
  const el = (t, c, h) => { const e = document.createElement(t); if (c) e.className = c; if (h != null) e.innerHTML = h; return e; };
  const money = (n) => '$' + Math.round(n).toLocaleString('en-US');
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

  let mode = 'play';           // 'play' | 'customize'
  let menuStack = [];
  let selIdx = 0;
  let goalShown = false;
  let toastTimer = null;

  /* ============================ boot ============================ */
  function boot() {
    const S = Game.init();
    buildMap();
    wireRail();
    if (!S.started || !S.player.name) showIntro(true);
    else { resetMenu(); refresh(); }
  }

  function refresh() {
    const S = Game.get();
    renderHUD(S);
    renderMap(S);
    renderScene(S);
    renderLog(S);
    renderMenu();
  }

  /* ============================ HUD ============================ */
  function renderHUD(S) {
    $('#statMoney').textContent = money(S.money);
    $('#statDay').textContent = '📅 Day ' + S.day;
    $('#statAp').textContent = `⚡ ${S.ap}/${Game.maxAp()}`;
    const fam = Game.wifeIds().length + S.children.length;
    $('#statFamily').innerHTML = `👨‍👩‍👧‍👦 ${fam}`;
    const pLv = Object.values(S.perks).reduce((a, b) => a + b, 0);
    $('#statPerks').textContent = `✨ Lv.${pLv}`;
    const g = Game.goalProgress();
    $('#goalFill').style.width = g.pct + '%';
    $('#goalText').textContent = `Happy Life: ${g.wives}/${g.wifeGoal} wives · ${g.kids}/${g.kidGoal} kids`;
    if (g.done && !goalShown) { goalShown = true; showGoalModal(g); }
  }

  /* ============================ MAP ============================ */
  function buildMap() {
    const svg = $('#map');
    const nodes = D.LOCATIONS.map((l) => `
      <g class="loc" data-id="${l.id}" transform="translate(${l.x},${l.y})">
        <rect x="-42" y="-19" width="84" height="38" rx="13" fill="#fff8fd" stroke="#ff9ec4" stroke-width="2.5"/>
        <text x="0" y="-2" text-anchor="middle" font-size="17">${l.icon}</text>
        <text x="0" y="12" text-anchor="middle" font-size="9.5" font-weight="700" fill="#a2578a" font-family="Fredoka, sans-serif">${l.name}</text>
      </g>`).join('');
    svg.innerHTML = `
      <defs>
        <linearGradient id="skyG" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#bfe9ff"/><stop offset="100%" stop-color="#ffe9f6"/>
        </linearGradient>
        <linearGradient id="seaG" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#7fd0f0"/><stop offset="100%" stop-color="#3f9fd0"/>
        </linearGradient>
      </defs>
      <rect width="600" height="300" fill="url(#skyG)"/>
      <circle cx="530" cy="40" r="24" fill="#ffe07a" opacity=".9"/>
      <g fill="#ffffff" opacity=".85">
        <ellipse cx="90" cy="42" rx="26" ry="12"/><ellipse cx="112" cy="36" rx="18" ry="10"/>
        <ellipse cx="430" cy="28" rx="22" ry="10"/><ellipse cx="452" cy="24" rx="14" ry="8"/>
      </g>
      <path d="M0,236 Q150,206 300,238 Q450,266 600,232 L600,300 L0,300 Z" fill="#a8e0a0"/>
      <path d="M392,262 Q480,238 600,258 L600,300 L380,300 Z" fill="url(#seaG)"/>
      <path d="M380,292 q14,-8 28,0 q14,8 28,0" stroke="#eafaff" stroke-width="2.5" fill="none" opacity=".8"/>
      <g stroke="#f6d9b0" stroke-width="7" stroke-linecap="round" fill="none" opacity=".95">
        <path d="M128,52 Q200,70 250,62 Q280,58 322,52"/>
        <path d="M322,52 Q370,60 396,96 Q420,120 400,176 Q386,200 300,150 Q240,120 214,224"/>
        <path d="M250,62 Q260,110 300,150 Q340,190 452,236"/>
        <path d="M300,150 Q200,150 118,168"/>
        <path d="M400,176 Q440,160 486,148"/>
        <path d="M214,224 Q260,200 300,150"/>
      </g>
      <g fill="#ffb7d5" opacity=".9">
        <circle cx="96" cy="196" r="15"/><circle cx="120" cy="204" r="12"/><circle cx="76" cy="204" r="10"/>
        <rect x="104" y="204" width="5" height="22" fill="#b98a63"/>
      </g>
      <g fill="#8fd3f4" opacity=".55"><circle cx="560" cy="196" r="4"/><circle cx="544" cy="212" r="3"/><circle cx="576" cy="214" r="3"/></g>
      <g font-family="Fredoka, sans-serif">${nodes}</g>
      <g id="marker">
        <ellipse cx="0" cy="6" rx="12" ry="4" fill="#000" opacity=".18"/>
        <path d="M0,-44 c-11,0 -20,9 -20,20 c0,14 20,30 20,30 s20,-16 20,-30 c0,-11 -9,-20 -20,-20 Z" fill="#ff6fae" stroke="#fff" stroke-width="3"/>
        <text id="markerTxt" x="0" y="-22" text-anchor="middle" font-size="16">♂</text>
      </g>`;
    svg.addEventListener('click', (e) => {
      const g = e.target.closest('.loc');
      if (g) travelTo(g.dataset.id);
    });
  }

  function renderMap(S) {
    document.querySelectorAll('.loc').forEach((n) => n.classList.toggle('here', n.dataset.id === S.location));
    const l = D.locById(S.location);
    const m = $('#marker');
    if (m) m.setAttribute('transform', `translate(${l.x},${l.y - 24})`);
    const t = $('#markerTxt');
    if (t) t.textContent = S.player.gender === 'female' ? '♀' : '♂';
  }

  function travelTo(id) {
    const r = Game.travel(id);
    toast(r.msg);
    refresh();
  }

  /* ============================ SCENE ============================ */
  function portraitOf(char) { return P.portrait(char, { bg: true }); }

  function affBar(S, girlId) {
    const a = S.girls[girlId].affection;
    const tier = Game.affectionTier(a);
    return `<div class="affbar"><i style="width:${a}%"></i></div>
      <div class="aff-txt" style="color:${tier.c}">${a}/100 · ${tier.t}</div>`;
  }

  function renderScene(S) {
    const scene = $('#scene');
    if (mode === 'customize') return renderPreview(S, scene);
    const loc = D.locById(S.location);
    let html = `<div class="loc-head"><span class="ic">${loc.icon}</span>
      <div><h2>${loc.name}</h2><p>${loc.blurb}</p></div></div>`;

    const here = Game.girlsHere();
    html += `<div class="sect"><h3>Women Here Today</h3>`;
    if (here.length === 0) {
      html += `<p style="font-size:13px;color:#9a7c8c">Nobody's around right now — check another spot on the map (▲▼ in the menu to browse actions).</p>`;
    } else {
      html += `<div class="cards">` + here.map((g) => {
        const gs = S.girls[g.id];
        return `<div class="card">
          ${portraitOf({ gender: 'female', look: g })}
          <div class="nm">${esc(g.name)} ${gs.married ? '<span class="badge wifey">WIFE</span>' : ''}</div>
          <div class="job">${g.job} · ${g.age}</div>
          ${affBar(S, g.id)}
        </div>`;
      }).join('') + `</div>`;
    }
    html += `</div>`;

    if (S.location === 'Home') {
      html += `<div class="sect"><h3>Your Family</h3>`;
      html += `<div class="cards">
        <div class="card">${portraitOf(S.player)}
