      }
    } else if (o.pattern === 'dots') {
      for (let i = 0; i < 12; i++) pat += `<circle cx="${24 + ((i * 31) % 112)}" cy="${Y + 12 + ((i * 23) % 68)}" r="2.6" fill="${accent}" opacity=".85"/>`;
