/* ---------------- outfit ---------------- */
function drawOutfit(o, body, skin, shoulderY, uid) {
  const base = o.base, accent = o.accent, trim = o.trim;
  const dark = T.shade(base, -0.22);
  const sw = body.sw;
  const hipY = 182;
  let out = '';

  // torso
  out += `<path d="M ${CX - sw},210 L ${CX - sw},${shoulderY + 14} Q ${CX - sw - 2},${shoulderY - 2} ${CX - 15},${shoulderY - 6}
    L ${CX + 15},${shoulderY - 6} Q ${CX + sw + 2},${shoulderY - 2} ${CX + sw},${shoulderY + 14} L ${CX + sw},210 Z"
    fill="${base}" stroke="${OUT}" stroke-width="2"/>`;
  // side cel shading
  out += `<path d="M ${CX + sw - 8},${shoulderY + 12} L ${CX + sw},210 L ${CX + sw - 14},210 L ${CX + sw - 16},${shoulderY + 14} Z" fill="${dark}" opacity=".45"/>`;

  // bare shoulders for sleeveless
  if (o.sleeve === 'none') {
    out += `<ellipse cx="${CX - sw + 2}" cy="${shoulderY + 2}" rx="10" ry="9" fill="${skin}" stroke="${OUT}" stroke-width="2"/>
    <ellipse cx="${CX + sw - 2}" cy="${shoulderY + 2}" rx="10" ry="9" fill="${skin}" stroke="${OUT}" stroke-width="2"/>`;
  }
  // sleeves
  if (o.sleeve === 'long') {
    out += `<path d="M ${CX - sw - 4},${shoulderY} L ${CX - sw + 6},206 L ${CX - sw + 20},206 L ${CX - sw + 14},${shoulderY + 4} Z" fill="${dark}" opacity=".8" stroke="${OUT}" stroke-width="2"/>
    <path d="M ${CX + sw + 4},${shoulderY} L ${CX + sw - 6},206 L ${CX + sw - 20},206 L ${CX + sw - 14},${shoulderY + 4} Z" fill="${base}" stroke="${OUT}" stroke-width="2"/>`;
  } else if (o.sleeve === 'short') {
    out += `<path d="M ${CX - sw - 4},${shoulderY} L ${CX - sw + 14},${shoulderY + 30} L ${CX - sw + 24},${shoulderY + 24} L ${CX - sw + 12},${shoulderY + 2} Z" fill="${dark}" opacity=".8" stroke="${OUT}" stroke-width="2"/>
    <path d="M ${CX + sw + 4},${shoulderY} L ${CX + sw - 14},${shoulderY + 30} L ${CX + sw - 24},${shoulderY + 24} L ${CX + sw - 12},${shoulderY + 2} Z" fill="${base}" stroke="${OUT}" stroke-width="2"/>`;
  } else if (o.sleeve === 'puffy') {
    const puffLight = T.shade(base, 0.5);
    out += `<ellipse cx="${CX - sw - 1}" cy="${shoulderY + 6}" rx="13" ry="12" fill="${base}" stroke="${OUT}" stroke-width="2"/>
    <ellipse cx="${CX + sw + 1}" cy="${shoulderY + 6}" rx="13" ry="12" fill="${base}" stroke="${OUT}" stroke-width="2"/>
    <ellipse cx="${CX - sw - 4}" cy="${shoulderY + 3}" rx="5" ry="4" fill="${puffLight}" opacity=".6"/>`;
  }

  // collar / neckline
  const ny = shoulderY - 6;
  const collarArt = {
    sailor: `<path d="M ${CX - 22},${ny} L ${CX},${ny + 26} L ${CX + 22},${ny} L ${CX + 15},${ny - 2} L ${CX},${ny + 14} L ${CX - 15},${ny - 2} Z" fill="${accent}" stroke="${OUT}" stroke-width="2"/>
      <path d="M ${CX - 20},${ny + 1} L ${CX},${ny + 22} L ${CX + 20},${ny + 1}" fill="none" stroke="${trim}" stroke-width="2.5"/>`,
    ribbon: `<path d="M ${CX - 20},${ny + 2} Q ${CX},${ny + 22} ${CX + 20},${ny + 2}" fill="none" stroke="${accent}" stroke-width="4"/>
      <path d="M ${CX - 12},${ny + 16} l 8,-5 l 4,7 l 4,-7 l 8,5 l -6,7 l -8,-2 l -8,2 Z" fill="${trim}" stroke="${OUT}" stroke-width="1.6"/>`,
    vneck: `<path d="M ${CX - 16},${ny} L ${CX},${ny + 24} L ${CX + 16},${ny}" fill="${T.shade(base, -0.3)}" stroke="${OUT}" stroke-width="2"/>`,
    turtleneck: `<path d="M ${CX - 15},${ny - 8} L ${CX - 14},${ny + 4} Q ${CX},${ny + 12} ${CX + 14},${ny + 4} L ${CX + 15},${ny - 8} Z" fill="${dark}" stroke="${OUT}" stroke-width="2"/>`,
    polo: `<path d="M ${CX - 14},${ny} L ${CX - 10},${ny + 20} L ${CX + 10},${ny + 20} L ${CX + 14},${ny} Z" fill="${T.shade(base, -0.18)}" stroke="${OUT}" stroke-width="2"/>
      <circle cx="${CX}" cy="${ny + 12}" r="2" fill="${trim}"/><circle cx="${CX}" cy="${ny + 22}" r="2" fill="${trim}"/>`,
    strap: `<path d="M ${CX - 16},${ny + 4} L ${CX - 12},${ny + 30}" stroke="${trim}" stroke-width="7" stroke-linecap="round"/>
      <path d="M ${CX + 16},${ny + 4} L ${CX + 12},${ny + 30}" stroke="${trim}" stroke-width="7" stroke-linecap="round"/>`,
    suit: `<path d="M ${CX - 18},${ny} L ${CX},${ny + 26} L ${CX - 6},${ny + 4} L ${CX - 20},${ny + 4} Z" fill="${accent}" stroke="${OUT}" stroke-width="2"/>
      <path d="M ${CX + 18},${ny} L ${CX},${ny + 26} L ${CX + 6},${ny + 4} L ${CX + 20},${ny + 4} Z" fill="${accent}" stroke="${OUT}" stroke-width="2"/>
      <path d="M ${CX},${ny + 26} l -4,6 l 4,26 l 4,-26 Z" fill="${trim}" stroke="${OUT}" stroke-width="1.6"/>`,
    cross: `<path d="M ${CX - 18},${ny} L ${CX + 6},${ny + 26} L ${CX - 12},${ny + 4}" fill="none" stroke="${trim}" stroke-width="3"/>
      <path d="M ${CX + 18},${ny} L ${CX - 6},${ny + 26} L ${CX + 12},${ny + 4}" fill="none" stroke="${trim}" stroke-width="3"/>`,
    round: `<path d="M ${CX - 17},${ny + 2} Q ${CX},${ny + 20} ${CX + 17},${ny + 2}" fill="none" stroke="${trim}" stroke-width="3"/>`,
    none: '',
  }[o.collar] || '';
  out += collarArt;

  // pattern overlay (clipped to torso)
  if (o.pattern && o.pattern !== 'none') {
    const clipId = 'clip' + uid;
    let pat = '';
    if (o.pattern === 'floral') {
      for (let i = 0; i < 9; i++) {
        const x = 26 + ((i * 37) % 108), y = shoulderY + 16 + ((i * 29) % 62);
        pat += `<g fill="${trim}" opacity=".8"><circle cx="${x}" cy="${y}" r="3"/><circle cx="${x + 5}" cy="${y + 3}" r="3"/><circle cx="${x - 5}" cy="${y + 3}" r="3"/><circle cx="${x}" cy="${y + 7}" r="3"/><circle cx="${x}" cy="${y + 3}" r="2" fill="${accent}"/></g>`;
      }
    } else if (o.pattern === 'dots') {
      for (let i = 0; i < 12; i++) pat += `<circle cx="${24 + ((i * 31) % 112)}" cy="${shoulderY + 12 + ((i * 23) % 68)}" r="2.6" fill="${accent}" opacity=".85"/>`;
    } else if (o.pattern === 'stripes') {
      for (let i = 0; i < 5; i++) pat += `<rect x="6" y="${shoulderY + 14 + i * 16}" width="148" height="6" fill="${accent}" opacity=".55"/>`;
    } else if (o.pattern === 'stars') {
      for (let i = 0; i < 8; i++) pat += `<path d="M ${28 + ((i * 41) % 104)},${shoulderY + 14 + ((i * 27) % 64)} l 3,6 l 7,1 l -5,5 l 1,7 l -6,-3 l -6,3 l 1,-7 l -5,-5 l 7,-1 Z" fill="${trim}" opacity=".8"/>`;
    }
    out += `<clipPath id="${clipId}"><path d="M ${CX - sw},210 L ${CX - sw},${shoulderY + 14} Q ${CX - sw - 2},${shoulderY - 2} ${CX - 15},${shoulderY - 6} L ${CX + 15},${shoulderY - 6} Q ${CX + sw + 2},${shoulderY - 2} ${CX + sw},${shoulderY + 14} L ${CX + sw},210 Z"/></clipPath>
    <g clip-path="url(#${clipId})">${pat}</g>`;
  }

  // frills
  if (o.frills) {
    let fr = '';
    for (let i = 0; i < 8; i++) fr += `<circle cx="${CX - sw + 6 + i * ((sw * 2 - 12) / 7)}" cy="${hipY + 16}" r="8" fill="${accent}" stroke="${OUT}" stroke-width="1.4"/>`;
    out += fr;
  }

  // lower body: skirt or pants
  if (o.skirt === 'pants') {
    out += `<path d="M ${CX - sw + 2},196 L ${CX - sw + 4},210 L ${CX - 4},210 L ${CX - 3},196 Z" fill="${dark}" stroke="${OUT}" stroke-width="1.6"/>
    <path d="M ${CX + sw - 2},196 L ${CX + sw - 4},210 L ${CX + 4},210 L ${CX + 3},196 Z" fill="${dark}" stroke="${OUT}" stroke-width="1.6"/>`;
  } else {
    const flare = o.skirt === 'gown' ? 34 : o.skirt === 'short' ? 14 : 22;
    const drop = o.skirt === 'gown' ? 28 : 16;
    out += `<path d="M ${CX - sw + 4},${hipY - 6} L ${CX - sw - flare},${hipY + drop} Q ${CX},${hipY + drop + 10} ${CX + sw + flare},${hipY + drop} L ${CX + sw - 4},${hipY - 6} Z" fill="${base}" stroke="${OUT}" stroke-width="2"/>`;
    if (o.skirt === 'pleat' || o.skirt === 'gown') {
      for (let i = -2; i <= 2; i++) out += `<path d="M ${CX + i * 9},${hipY - 4} L ${CX + i * (9 + flare / 3)},${hipY + drop + 2}" stroke="${dark}" stroke-width="2" opacity=".5" fill="none"/>`;
    }
    out += `<path d="M ${CX + sw - 6},${hipY - 4} L ${CX + sw + flare - 4},${hipY + drop} L ${CX + sw + flare - 12},${hipY + drop} Z" fill="${dark}" opacity=".35"/>`;
  }
  return out;
}

